$(() => {
  const 地区基础风险: Record<string, number> = {
    商业区: 70,
    老城区: 65,
    工业区: 45,
    住宅区: 40,
    公园: 25,
    地铁: 55,
    江城大学: 50,
  };
  const 醉汉地区 = ['住宅区', '商业区', '老城区', '公园'];
  const 小混混地区 = ['老城区', '工业区'];
  // 委托地点适配（二期）：只按地点名判断——地点的玩法线索在世界书里是定性描述，脚本不取数字
  const 跟随类地点 = ['商业步行街', '地铁车厢', '地铁换乘通道', '公交站台', '大型购物广场', '地下通道', '山河路', '夜市大排档', '老城大街'];
  const 交互类地点 = ['商业步行街', '大型购物广场', '地铁车厢', '小区便利店', '公交站台', '地下通道', '情趣商店', '成人用品店', '老城大街', '夜市大排档', '游泳池更衣室'];
  const 束缚类地点 = ['楼顶天台', '河边涵洞', '工地建材堆', '24 小时网吧包厢', '金桂苑地下车库', '购物广场地下停车场', '高层消防楼梯', '空置楼房', '密林小径', '游泳池更衣室', '废旧铁轨', '老城窄巷', '自助洗衣房'];
  const 补给类地点 = ['中心花园', '小区快递柜', '楼顶天台', '河边涵洞', '金桂苑地下车库', '工地建材堆', '废旧铁轨', '成人用品店', '大型购物广场', '情趣商店', '高层消防楼梯'];
  // 顾鸢只可能在她的活动范围出现：四个大区 + 住宅区内仅限翠湖家园（她的住处）
  const 顾鸢地区 = ['商业区', '老城区', '工业区', '公园'];
  function 可遇顾鸢(区域: string, 地点: string): boolean {
    if (顾鸢地区.includes(区域)) return true;
    return 区域 === '住宅区' && 地点.startsWith('翠湖家园');
  }

  function 时段(小时: number): string {
    if (小时 >= 6 && 小时 < 9) return '早晨';
    if (小时 >= 9 && 小时 < 18) return '白天';
    if (小时 >= 18 && 小时 < 22) return '晚上';
    return '深夜';
  }

  function 是否露出(穿着: Record<string, string>, 束缚: Record<string, string>): boolean {
    const 关键穿着 = ['上衣', '下装', '胸罩', '内裤'];
    if (关键穿着.some(k => !穿着?.[k] || 穿着[k] === '无')) return true;
    const 显眼束缚 = ['眼部', '口部', '脚踝'];
    if (显眼束缚.some(k => 束缚?.[k] && 束缚[k] !== '无')) return true;
    return false;
  }

  function 露出档(经验: number): string {
    if (经验 < 60) return '初尝';
    if (经验 < 160) return '试探';
    if (经验 < 300) return '大胆';
    if (经验 < 420) return '放纵';
    return '无惧';
  }

  function 注入事件(文本: string) {
    injectPrompts(
      [{ id: 'random_event', position: 'in_chat', depth: 0, role: 'system', content: 文本 }],
      { once: true },
    );
  }

  eventOn(tavern_events.GENERATION_STARTED, async () => {
    await waitGlobalInitialized('Mvu');
    if (Mvu.isDuringExtraAnalysis()) return;

    const data = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
    const stat = _.get(data, 'stat_data');
    if (!stat) return;

    const 区域: string = stat.位置?.区域 ?? '';
    const 地点: string = stat.位置?.地点 ?? '';
    const 小时: number = Number(stat.时间?.小时 ?? 12);
    const 段 = 时段(小时);
    const 露出 = 是否露出(stat.穿着 ?? {}, stat.束缚 ?? {});
    const 性欲 = Number(stat.性欲值 ?? 0);

    // 天气：全局，任何时候可触发
    if (Math.random() < 0.05) {
      注入事件(
        '【随机事件·天气】天气发生了变化（如下雨、起风、降温等，由你随机选择一种，要符合当前时段）。请在正文中自然体现天气变化对江星晚的影响。',
      );
      return;
    }

    // ── 圈子委托（二期）：有单在身不派；只从当前档《任务库》取 ──────────
    const 任务表: any[] = Array.isArray(stat.$任务) ? stat.$任务 : [];
    const 有单在身 = 任务表.some((t: any) => t?.状态 === '待接' || t?.状态 === '进行中');
    if (!有单在身) {
      const 经验 = Number(stat.露出经验 ?? 0);
      const 档 = 露出档(经验);
      const 适配型: string[] = ['A'];
      if (跟随类地点.includes(地点)) 适配型.push('B');
      if (交互类地点.includes(地点)) 适配型.push('C');
      if (束缚类地点.includes(地点)) 适配型.push('D');
      if (补给类地点.includes(地点)) 适配型.push('E');
      if (适配型.length >= 3 && 经验 >= 160) 适配型.push('F');

      // 紧急委托 4% 起：深夜、有经验、正露着的时候更容易有人想起她
      let 委托概率 = 0.04;
      if (段 === '深夜') 委托概率 += 0.02;
      if (经验 >= 160) 委托概率 += 0.01;
      if (露出) 委托概率 += 0.01;

      if (Math.random() < 委托概率) {
        注入事件(
          `【圈子委托·派发】这一次会有一条「${档}」档的委托找上江星晚，必须在正文里送到她手上，不能跳过。\n` +
            `- 只能从世界书《任务库_${档}》里挑一条，优先 ${适配型.join(' / ')} 型、且与当前所在「${区域}·${地点}」相合的；本地没有相合条目时，挑一条能把她引到附近地点的，把移动过程写出来。\n` +
            `- 委托必须具体到达：论坛私信、苏遥发来的消息、顾鸢打来的电话，或塞进门缝的纸条——写清是谁派的、要她做什么、拿什么换、限期到什么时候。\n` +
            `- 她答应后把这一条写进 \`$任务\`（状态按她是否当场动身填「待接」或「进行中」；id 用 T-<月日>-<两位序号>，内容末尾标（库 Xn））。\n` +
            `- 她也可以拒绝，但要写清拒绝的代价。绝不硬塞、不替她答应。`,
        );
        return;
      }
    }

    if (露出) {
      const 风险 = 地区基础风险[区域] ?? 40;
      let 概率 = 0.1 + 风险 * 0.002;
      if (段 === '深夜') 概率 += 0.05;
      if (性欲 > 80) 概率 += 0.05;

      if (Math.random() < 概率) {
        const 可小混混 = 小混混地区.includes(区域);
        const 可醉汉 = 醉汉地区.includes(区域);
        if (可小混混 && Math.random() < 0.5) {
          注入事件(
            '【随机事件·小混混】几个小混混在附近游荡，注意到了江星晚，不怀好意地靠了过来。请自然演绎这次冲突，对方可能勒索、动手，甚至把她带走。',
          );
        } else if (可醉汉) {
          注入事件(
            '【随机事件·醉汉】一个满身酒气的醉汉摇摇晃晃地朝江星晚这边走来，似乎注意到了她。请自然演绎这次偶遇。',
          );
        } else {
          注入事件(
            '【随机事件·路人】有路人注意到江星晚的异样，犹豫后上前询问她是否身体不适、需不需要帮忙。请自然演绎这次对话。',
          );
        }
        return;
      }

      // 路人询问：独立低概率
      if (Math.random() < 0.05) {
        注入事件(
          '【随机事件·路人】有路人注意到江星晚的异样举动，犹豫了一下，上前询问她是否身体不适、需不需要帮忙。请自然演绎这次对话。',
        );
        return;
      }

      // 丢钥匙：自缚时
      const 有束缚 = Object.values(stat.束缚 ?? {}).some((v: string) => v && v !== '无');
      if (有束缚 && Math.random() < 0.04) {
        注入事件(
          '【随机事件·丢钥匙】江星晚发现自己藏起的自缚钥匙不见了（或从身上掉落）。她此刻正被束缚着，必须找回钥匙才能解开。请自然演绎这份慌乱与失控。',
        );
        return;
      }
    }

    // 同好偶遇：仅限晚上与深夜——顾鸢的野外玩法是夜间活动，白天撞破不合逻辑；
    // 只保留涉及「玩」的组合，普通状态偶遇没有戏剧情境，撞破秘密才是关系发展的种子。
    // 星晚在玩时 3%；星晚没在玩时需掷中顾鸢正在玩（30%），实际约 0.9%，掷不中本次放过
    if (小时 >= 18 && 可遇顾鸢(区域, 地点) && Math.random() < 0.03) {
      const 顾鸢露出 = Math.random() < 0.3;
      if (!露出) {
        if (顾鸢露出) {
          注入事件(
            '【随机事件·同好】江星晚偶然撞见同好顾鸢正在某个隐蔽处玩自缚露出。请自然演绎这个尴尬又兴奋的场景。',
          );
          return;
        }
      } else if (!顾鸢露出) {
        注入事件(
          '【随机事件·同好】江星晚正在露出时，被恰好路过的同好顾鸢撞见。请自然演绎顾鸢的反应——她大概会心照不宣地帮她望风或解围。',
        );
        return;
      } else {
        注入事件(
          '【随机事件·同好】江星晚正在露出时，遇到了同样在玩露出的顾鸢。两人相视会心一笑，可能一起继续这场游戏。请自然演绎。',
        );
        return;
      }
    }

    // 被闺蜜撞见：仅限商业区/江城大学/公园/地铁 + 山河景苑小区内居民楼之外的公共地点
    // 林知夏住四单元一号楼，与星晚不同楼栋，在自家楼内/家门口/天台「偶遇」不合地理逻辑
    const 闺蜜地区 = ['商业区', '江城大学', '公园', '地铁'];
    const 山河景苑公共地点 = ['山河景苑小区大门', '小区便利店', '中心花园'];
    const 可遇闺蜜 = 闺蜜地区.includes(区域) || (区域 === '住宅区' && 山河景苑公共地点.includes(地点));
    if (可遇闺蜜 && Math.random() < 0.02) {
      注入事件(
        '【随机事件·闺蜜】江星晚的闺蜜林知夏恰好出现在附近，似乎注意到了她的异样。请自然演绎这个可能暴露秘密的时刻。',
      );
      return;
    }
  });
});
